import{_ as t,o as r,c as o,ah as a}from"./chunks/framework.C-FRNfAJ.js";const h=JSON.parse('{"title":"Les cohortes","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/coordinateur/cohortes.md","filePath":"src/guide/coordinateur/cohortes.md"}'),n={name:"guide/coordinateur/cohortes.md"};function s(i,e,l,d,u,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="les-cohortes" tabindex="-1">Les cohortes <a class="header-anchor" href="#les-cohortes" aria-label="Permalink to &quot;Les cohortes&quot;">​</a></h1><p>Une cohorte est une session programmée d&#39;un programme, rattachée à une promotion. Elle a <strong>15 apprenants au plus</strong> et peut mêler les trois formats : le format et le prix sont portés par chaque inscription, pas par la cohorte.</p><h2 id="ouvrir-une-cohorte" tabindex="-1">Ouvrir une cohorte <a class="header-anchor" href="#ouvrir-une-cohorte" aria-label="Permalink to &quot;Ouvrir une cohorte&quot;">​</a></h2><p><strong>Formation → Cohortes → Ouvrir une cohorte.</strong> Le formulaire liste les programmes et indique, pour chacun, ce qui l&#39;empêche d&#39;ouvrir :</p><ul><li>programme <strong>non publié</strong> ;</li><li><strong>banque QCM non validée</strong> ;</li><li><strong>prix manquant</strong> dans la grille pour un format proposé.</li></ul><p>Renseignez ensuite :</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Promotion et année</td><td>Baobab (septembre), Iroko (décembre), Acacia (mars) ou Karité (juin). Une seule cohorte par programme, promotion et année</td></tr><tr><td>Dates</td><td>Début et fin. La fin au plus tôt à la durée du programme (25 ou 12 semaines) ; le temps partiel l&#39;allonge, saisissez la date réelle</td></tr><tr><td>Profil de rythme</td><td>Temps plein ou temps partiel, à titre indicatif</td></tr><tr><td>Formateurs principaux</td><td>Au moins un. Obligatoire</td></tr><tr><td>Coachs-tuteurs</td><td>Facultatifs</td></tr></tbody></table><p>À l&#39;ouverture, <strong>les prix de la grille sont figés</strong> sur la cohorte. La mi-parcours et les dates des trois échéances (30/40/30) sont <strong>calculées</strong>, jamais saisies : 30 % au début (ou à la signature si elle est postérieure), 40 % à la mi-parcours, 30 % à la fin.</p><h2 id="le-cycle-de-vie" tabindex="-1">Le cycle de vie <a class="header-anchor" href="#le-cycle-de-vie" aria-label="Permalink to &quot;Le cycle de vie&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Statut</th><th>Ce qui le provoque</th></tr></thead><tbody><tr><td><strong>Ouverte</strong></td><td>À l&#39;ouverture</td></tr><tr><td><strong>Confirmée</strong></td><td>Vous cliquez sur <strong>Confirmer</strong></td></tr><tr><td><strong>En cours</strong></td><td>Automatiquement, à la date de début d&#39;une cohorte confirmée</td></tr><tr><td><strong>Terminée</strong></td><td>Automatiquement, après sa date de fin. Ses inscriptions actives et suspendues passent « terminées »</td></tr><tr><td><strong>Reportée</strong>, <strong>Annulée</strong></td><td>Vous le décidez, avant le démarrage</td></tr></tbody></table><p>Dates, rythme et encadrement restent modifiables <strong>jusqu&#39;au démarrage</strong> ; les prix figés ne changent pas.</p><h3 id="reporter-ou-annuler" tabindex="-1">Reporter ou annuler <a class="header-anchor" href="#reporter-ou-annuler" aria-label="Permalink to &quot;Reporter ou annuler&quot;">​</a></h3><p>Un <strong>report</strong> ou une <strong>annulation</strong> n&#39;est possible qu&#39;avant le démarrage, avec un <strong>motif obligatoire</strong>, et la décision est <strong>définitive</strong> et journalisée.</p><ul><li><strong>Report</strong> : vous choisissez la <strong>cohorte de remplacement</strong>, une cohorte à venir du même programme, avec une place et un prix pour chaque apprenant. Toutes les inscriptions non abandonnées y passent.</li><li><strong>Annulation</strong> : les inscriptions passent « sans cohorte ». Vous replacez chaque apprenant ou vous enregistrez son abandon.</li></ul><p>Les conséquences financières suivent les règles de facturation (voir <a href="./facturation.html#si-une-cohorte-change-ou-est-annulee">Facturation</a>).</p><h2 id="le-cours-seve-de-la-cohorte" tabindex="-1">Le cours Sève de la cohorte <a class="header-anchor" href="#le-cours-seve-de-la-cohorte" aria-label="Permalink to &quot;Le cours Sève de la cohorte&quot;">​</a></h2><p>Sur la fiche de la cohorte, renseignez l&#39;<strong>identifiant du cours Sève</strong>. Chaque apprenant y est inscrit dès sa première tranche payée ; sans identifiant, ses inscriptions attendent. Il est aussi nécessaire pour que les classes virtuelles et les notes remontent dans Kura.</p><h2 id="les-zones-de-rentabilite" tabindex="-1">Les zones de rentabilité <a class="header-anchor" href="#les-zones-de-rentabilite" aria-label="Permalink to &quot;Les zones de rentabilité&quot;">​</a></h2><p>Kura classe chaque cohorte selon son <strong>effectif confirmé</strong> (les inscriptions signées) :</p><table tabindex="0"><thead><tr><th>Zone</th><th>Effectif par défaut</th></tr></thead><tbody><tr><td>Fragile</td><td>Moins de 7</td></tr><tr><td>Viable</td><td>7 à 11</td></tr><tr><td>Confortable</td><td>12 à 15</td></tr></tbody></table><p>L&#39;Administrateur règle les seuils par catégorie. Une cohorte qui démarre <strong>fige sa zone</strong> avec son effectif : un changement de seuil ne touche que les cohortes à venir.</p><h3 id="le-tableau-de-bord-de-rentabilite" tabindex="-1">Le tableau de bord de rentabilité <a class="header-anchor" href="#le-tableau-de-bord-de-rentabilite" aria-label="Permalink to &quot;Le tableau de bord de rentabilité&quot;">​</a></h3><p><strong>Formation → Rentabilité</strong> présente les cohortes ouvertes et confirmées, avec :</p><ul><li>leur zone et leur effectif face aux seuils ;</li><li>les <strong>recettes signées</strong>, et celles en attente de signature ;</li><li>le <strong>coût de l&#39;encadrement</strong> et la part couverte par les recettes ;</li><li>une cohorte <strong>« À décider »</strong> : fragile à moins d&#39;une semaine du démarrage, placée en tête.</li></ul><p>En zone fragile, le tableau recommande d&#39;envisager un report. <strong>Il ne déclenche rien</strong> : la décision vous revient.</p><h2 id="la-fiche-de-la-cohorte" tabindex="-1">La fiche de la cohorte <a class="header-anchor" href="#la-fiche-de-la-cohorte" aria-label="Permalink to &quot;La fiche de la cohorte&quot;">​</a></h2><p>La fiche rassemble le calendrier, l&#39;échéancier, les prix figés, le cours Sève, l&#39;encadrement, les apprenants (avec le repère « Pas de droit à l&#39;image »), et des liens vers la <strong>présence</strong> et les <strong>résultats</strong>.</p><p>Le panneau <strong>Documents</strong> génère à la demande :</p><ul><li>le <strong>calendrier prévisionnel</strong> (pour tous ceux qui voient la cohorte) ;</li><li>le <strong>rapport d&#39;activité</strong> : places, présence, résultats (pour vous et l&#39;Administrateur) ;</li><li>le <strong>PV de soutenance</strong>, voir <a href="./resultats.html">Résultats et certification</a>.</li></ul>',29)])])}const g=t(n,[["render",s]]);export{h as __pageData,g as default};
